// Destructive cleanup is restricted to databases generated by this isolated test.
const {test}=require('node:test'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{Client}=require('pg'),{spawnSync}=require('node:child_process'),path=require('node:path');
const {setup}=require('./helpers.cjs');
test('PostgreSQL 17: dedicated non-owner login, startup guard, RLS and protected fields',{timeout:120000},async()=>{
 if(process.env.NODE_ENV!=='test'||process.env.LUMAVOK_ALLOW_DISPOSABLE_DATABASE!=='1')throw new Error('Explicit disposable database test environment required');
 const base=new URL(process.env.LUMAVOK_NATIVE_TEST_URL);if(!['localhost','127.0.0.1','[::1]'].includes(base.hostname))throw new Error('Native test accepts loopback hosts only');
 const admin=new Client({connectionString:base.toString()});await admin.connect();try{
  const version=Number((await admin.query('SHOW server_version_num')).rows[0].server_version_num);assert.ok(version>=170000&&version<180000,'PostgreSQL 17 required');
  for(const observed of [false,true]){
   const suffix=crypto.randomBytes(8).toString('hex'),database='lumavok_test_'+suffix,login='lumavok_login_'+suffix,password=crypto.randomBytes(32).toString('hex');
   await admin.query(`CREATE DATABASE "${database}"`);const ownerURL=new URL(base);ownerURL.pathname='/'+database;const owner=new Client({connectionString:ownerURL.toString()});await owner.connect();let client;
   try{
    class NativeDatabase{async exec(sql){return owner.query(sql.replace(/CREATE ROLE (anon|authenticated|service_role|supabase_admin);/g,(_,role)=>`DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='${role}') THEN CREATE ROLE ${role}; END IF; END $$;`))}async query(sql,args){return owner.query(sql,args)}}
    await setup(observed,NativeDatabase);
    await admin.query(`CREATE ROLE "${login}" LOGIN INHERIT NOBYPASSRLS NOCREATEDB NOCREATEROLE PASSWORD '${password}'`);await admin.query(`GRANT lumavok_runtime TO "${login}"`);
    const runtimeURL=new URL(ownerURL);runtimeURL.username=login;runtimeURL.password=password;client=new Client({connectionString:runtimeURL.toString()});await client.connect();
    assert.equal((await client.query('SELECT current_user=session_user AS same')).rows[0].same,true);
    assert.deepEqual((await client.query('SELECT id FROM public.property ORDER BY id')).rows.map(r=>r.id),['p1']);
    await assert.rejects(client.query('SET ROLE postgres'));
    await client.query('BEGIN');await client.query("SELECT set_config('lumavok.user_id','u1',true),set_config('lumavok.role','PROPERTY_DEVELOPER',true),set_config('lumavok.developer_id','dev1',true)");
    assert.equal((await client.query("UPDATE public.property SET title='stolen' WHERE id='draft'")).rowCount,0);await assert.rejects(client.query(`UPDATE public."user" SET role='ADMIN' WHERE id='u1'`));await client.query('ROLLBACK');
    assert.deepEqual((await client.query('SELECT id FROM public.property ORDER BY id')).rows.map(r=>r.id),['p1']);
    const cwd=path.resolve(__dirname,'../../../backend');const result=spawnSync(process.execPath,['--import','tsx','--input-type=module','-e',`const {assertRuntimeRole,prisma}=await import('./src/config/prisma.ts');try{await assertRuntimeRole();}finally{await prisma.$disconnect()}`],{cwd,env:{...process.env,DATABASE_URL:runtimeURL.toString()},encoding:'utf8'});assert.equal(result.status,0,'Dedicated runtime login must pass startup guard');
   }finally{if(client)await client.end();await owner.end();await admin.query(`DROP DATABASE "${database}" WITH(FORCE)`);await admin.query(`DROP ROLE IF EXISTS "${login}"`)}
  }
 }finally{await admin.end()}
});
